import { resolve } from 'node:path';
import { readFileSync } from 'node:fs';
export function download(request, base) {
  const candidate = resolve(base, request.query.name);
  if (!candidate.startsWith(resolve(base))) throw new Error('forbidden');
  return readFileSync(candidate, 'utf8');
}

